ALTER TABLE "requirement_workspace_versions" ADD CONSTRAINT "requirement_workspace_versions_assignmentId_fkey" FOREIGN KEY ("assignmentId") REFERENCES "compliance_requirement_assignments"("id") ON DELETE CASCADE;
ALTER TABLE "requirement_collaboration_entries" ADD CONSTRAINT "requirement_collaboration_entries_assignmentId_fkey" FOREIGN KEY ("assignmentId") REFERENCES "compliance_requirement_assignments"("id") ON DELETE CASCADE;
